  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Function to process transactions file
  const processTransactionsFile = async (file, headers, mappedFields) => {
    setLoading(true);
    setError(null);

    try {
      // Read the file
      const text = await readFileAsText(file);
      const lines = text.split('\n');

      if (lines.length <= 1) {
        throw new Error('File is empty or contains only headers');
      }

      // Parse headers
      const headerLine = lines[0];
      const headerFields = headerLine.split(',').map(h => h.trim());

      // Parse transactions
      const transactions = [];
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue; // Skip empty lines

        const values = line.split(',').map(v => v.trim());
        const transaction = {};

        // Map fields based on the provided mappings
        Object.keys(mappedFields).forEach(field => {
          const headerIndex = headerFields.indexOf(mappedFields[field]);
          if (headerIndex !== -1) {
            transaction[field] = values[headerIndex];
          }
        });

        // Add only if we have the minimum required fields
        if (transaction.symbol && transaction.date && transaction.action && transaction.quantity && transaction.price) {
          // Convert quantity and price to numbers
          transaction.quantity = parseFloat(transaction.quantity);
          transaction.price = parseFloat(transaction.price);
          transaction.brokerage = transaction.brokerage ? parseFloat(transaction.brokerage) : 0;

          transactions.push(transaction);
        }
      }

      // Calculate portfolio summary from transactions
      const holdings = calculateHoldings(transactions);

      // Simulate getting current prices (in a real app, this would call Yahoo Finance API)
      const holdingsWithCurrentPrices = simulateCurrentPrices(holdings);

      // Create portfolio object
      const newPortfolio = {
        name: 'My Portfolio',
        type: 'Transactions-based',
        lastUpdated: new Date().toISOString(),
        transactions: transactions,
        holdings: holdingsWithCurrentPrices,
        totalValue: holdingsWithCurrentPrices.reduce((sum, h) => sum + h.currentValue, 0),
        investedValue: holdingsWithCurrentPrices.reduce((sum, h) => sum + h.valueAtCost, 0),
        performanceMetrics: calculatePerformanceMetrics(holdingsWithCurrentPrices, transactions)
      };

      // Calculate sector allocation
      newPortfolio.sectorAllocation = calculateSectorAllocation(holdingsWithCurrentPrices);

      // Calculate unrealized return
      if (newPortfolio.investedValue > 0) {
        newPortfolio.unrealizedReturn = ((newPortfolio.totalValue - newPortfolio.investedValue) / newPortfolio.investedValue) * 100;
      } else {
        newPortfolio.unrealizedReturn = 0;
      }

      setPortfolio(newPortfolio);
      setLoading(false);
      return newPortfolio;

    } catch (error) {
      console.error('Error processing transactions file:', error);
      setError('Failed to process transactions file: ' + error.message);
      setLoading(false);
      return null;
    }
  };

